add_action( 'admin_bar_menu', 'perfectpixel_share_cart_admin_bar', 100 );
add_action( 'wp_loaded', 'perfectpixel_share_cart_load', 20 );

function perfectpixel_share_cart_url() {
	if ( ! function_exists( 'WC' ) || ! WC()->cart || WC()->cart->is_empty() ) {
		return '';
	}
	$items = array();
	foreach ( WC()->cart->get_cart() as $item ) {
		$id      = $item['variation_id'] ? $item['variation_id'] : $item['product_id'];
		$items[] = $id . ':' . (int) $item['quantity'];
	}
	$args = array( 'perfectpixel_cart' => implode( ',', $items ) );
	if ( WC()->cart->get_applied_coupons() ) {
		$args['perfectpixel_coupons'] = implode( ',', WC()->cart->get_applied_coupons() );
	}
	return add_query_arg( $args, home_url( '/' ) );
}

function perfectpixel_share_cart_admin_bar( $bar ) {
	if ( is_admin() || ! current_user_can( 'manage_woocommerce' ) ) {
		return;
	}
	$url = perfectpixel_share_cart_url();
	if ( ! $url ) {
		return;
	}
	$bar->add_node(
		array(
			'id'    => 'perfectpixel-share-cart',
			'title' => esc_html( '{{share_cart_label}}' ),
			'href'  => esc_url( $url ),
			'meta'  => array( 'onclick' => 'navigator.clipboard.writeText(this.href);this.textContent="✓";return false;' ),
		)
	);
}

function perfectpixel_share_cart_load() {
	if ( empty( $_GET['perfectpixel_cart'] ) || ! function_exists( 'WC' ) || ! WC()->cart ) { // phpcs:ignore WordPress.Security.NonceVerification
		return;
	}
	WC()->cart->empty_cart();
	foreach ( explode( ',', sanitize_text_field( wp_unslash( $_GET['perfectpixel_cart'] ) ) ) as $pair ) { // phpcs:ignore WordPress.Security.NonceVerification
		list( $id, $qty ) = array_pad( array_map( 'absint', explode( ':', $pair ) ), 2, 1 );
		$product = $id ? wc_get_product( $id ) : false;
		if ( ! $product ) {
			continue;
		}
		if ( $product->is_type( 'variation' ) ) {
			WC()->cart->add_to_cart( $product->get_parent_id(), max( 1, $qty ), $id, $product->get_variation_attributes() );
		} else {
			WC()->cart->add_to_cart( $id, max( 1, $qty ) );
		}
	}
	if ( ! empty( $_GET['perfectpixel_coupons'] ) ) { // phpcs:ignore WordPress.Security.NonceVerification
		foreach ( explode( ',', sanitize_text_field( wp_unslash( $_GET['perfectpixel_coupons'] ) ) ) as $code ) { // phpcs:ignore WordPress.Security.NonceVerification
			WC()->cart->apply_coupon( wc_format_coupon_code( $code ) );
		}
	}
	wp_safe_redirect( wc_get_checkout_url() );
	exit;
}
